import{_ as a,o as t,c as i,au as r}from"./chunks/framework.CKsBWDFD.js";import"./chunks/theme.Buk3xez4.js";const p=JSON.parse('{"title":"Elemental Reactions","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"guide/elements/Elemental_Reactions.md","filePath":"guide/elements/Elemental Reactions.md","lastUpdated":1783267680000}'),n={name:"guide/elements/Elemental_Reactions.md"};function o(l,e,s,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="Elemental_Reactions" tabindex="-1">Elemental Reactions <a class="header-anchor" href="#Elemental_Reactions" aria-label="Permalink to “Elemental Reactions”">​</a></h1><p>An <strong>Elemental Reaction</strong> is the result of combining two valid elements together! Each reaction has its own effect, which can be used to your advantage!</p><h2 id="Transformative_Reactions" tabindex="-1">Transformative Reactions <a class="header-anchor" href="#Transformative_Reactions" aria-label="Permalink to “Transformative Reactions”">​</a></h2><p><strong>Transformative Reactions</strong> are reactions that have their own instance of damage. This means that the target receives two <em>hits</em>: one from the attack, and one from the reaction.</p><p>The damage dealt by these reactions scale off the <code>levelMultiplier</code> game rule and their specific <em>Reaction Multiplier</em>. They also bypass Shields and the DMG cooldown, have no impact, deal no knockback and do not trigger the DMG cooldown timer.</p><h3 id="List" tabindex="-1">List <a class="header-anchor" href="#List" aria-label="Permalink to “List”">​</a></h3><ul><li><a href="../../Overloaded">Overloaded</a></li><li><a href="../../Electro-Charged">Electro-Charged</a></li><li><a href="../../Superconduct">Superconduct</a></li><li><a href="../../Frozen#Shatter">Shatter</a></li><li><a href="../../Swirl">Swirl</a></li><li><a href="../../Burning">Burning</a></li><li><a href="../../Bloom">Bloom</a></li><li><a href="../../Bloom#Hyperbloom">Hyperbloom</a></li><li><a href="../../Bloom#Burgeon">Burgeon</a></li></ul><h2 id="Amplifying_Reactions" tabindex="-1">Amplifying Reactions <a class="header-anchor" href="#Amplifying_Reactions" aria-label="Permalink to “Amplifying Reactions”">​</a></h2><p><strong>Amplifying Reactions</strong> are reactions that <strong>amplify</strong> the damage that triggered the reaction.</p><p>These reactions apply a <strong>multiplier</strong> on the damage that triggered the reaction, amplifying the damage further.</p><h3 id="List-1" tabindex="-1">List <a class="header-anchor" href="#List-1" aria-label="Permalink to “List”">​</a></h3><ul><li><a href="../../Melt">Melt</a></li><li><a href="../../Vaporize">Vaporize</a></li></ul><h2 id="Additive_Reactions" tabindex="-1">Additive Reactions <a class="header-anchor" href="#Additive_Reactions" aria-label="Permalink to “Additive Reactions”">​</a></h2><p><strong>Additive Reactions</strong> are reactions that <strong>add</strong> onto the damage that triggered the reaction.</p><p>These reactions apply an <strong>additive bonus</strong> that scales on the <code>levelMultiplier</code> game rule, applied as <strong>early</strong> as possible. For players, this is applied <strong>after</strong> the weapon damage and the <strong>1.5x</strong> CRIT hit multiplier.</p><h3 id="List-2" tabindex="-1">List <a class="header-anchor" href="#List-2" aria-label="Permalink to “List”">​</a></h3><ul><li><a href="../../Quicken#Spread">Spread</a></li><li><a href="../../Quicken#Aggravate">Aggravate</a></li></ul><h2 id="Other_Reactions" tabindex="-1">Other Reactions <a class="header-anchor" href="#Other_Reactions" aria-label="Permalink to “Other Reactions”">​</a></h2><p>These are the other reactions not classified as any of the above, and are usually ones that apply effects or other Elemental Auras that allow you to trigger a new set of reactions not triggerable with the standard seven Elements.</p><h3 id="List-3" tabindex="-1">List <a class="header-anchor" href="#List-3" aria-label="Permalink to “List”">​</a></h3><ul><li><a href="../../Frozen">Frozen</a></li><li><a href="../../Quicken">Quicken</a></li><li><a href="../../Crystallize">Crystallize</a></li></ul>',21)])])}const f=a(n,[["render",o]]);export{p as __pageData,f as default};
